with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__CONTRACT_ID_MEMBER_ID))) as HUB_RISK_OBJECT_HK
        , GMC_DISEASE_TO_BE_EXCLUDED as CONDITION_NAME
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
    where (nullif('MEMBER:' || coalesce(nullif(trim(CONTRACT_ID),''),'') || '#' || coalesce(nullif(trim(MEMBER_ID),''),''), 'MEMBER:#')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CONDITION_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONDITION_NAME end)) as CONDITION_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when CONDITION_NAME is not null
                     then md5(upper(coalesce(cast(CONDITION_NAME as varchar), '')))
                end as SAT_RISK_HEALTH_PED_WAITING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_HEALTH_PED_WAITING_HASHDIFF is not null
